{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js"
  }
}
import { createServer } from 'node:http';
import { readFile } from 'node:fs/promises';
import { DatabaseSync } from 'node:sqlite';
import { fileURLToPath } from 'node:url';
import { dirname, join } from 'node:path';

const root = dirname(fileURLToPath(import.meta.url));
const database = new DatabaseSync(process.env.DB_PATH || join(root, 'workboard.sqlite'));
database.exec(`
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL
  )
  ;
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
    title TEXT NOT NULL,
    completed INTEGER NOT NULL DEFAULT 0,
    priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))
  )
`);
database.exec('PRAGMA foreign_keys = ON');
try { database.exec('ALTER TABLE projects ADD COLUMN archived INTEGER NOT NULL DEFAULT 0'); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
try { database.exec("ALTER TABLE projects ADD COLUMN default_task_priority TEXT NOT NULL DEFAULT 'Normal' CHECK (default_task_priority IN ('Low', 'Normal', 'High'))"); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
try { database.exec("ALTER TABLE tasks ADD COLUMN priority TEXT NOT NULL DEFAULT 'Normal' CHECK (priority IN ('Low', 'Normal', 'High'))"); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
try { database.exec('ALTER TABLE tasks ADD COLUMN due_date TEXT'); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
try { database.exec('ALTER TABLE tasks ADD COLUMN sort_order INTEGER'); } catch (error) {
  if (!String(error.message).includes('duplicate column name')) throw error;
}
database.exec('UPDATE tasks SET sort_order = id WHERE sort_order IS NULL');

const listProjects = database.prepare(`SELECT p.id, p.name, p.archived, p.default_task_priority AS defaultTaskPriority,
  (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id AND t.completed = 1) AS completedCount,
  (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id) AS totalCount
  FROM projects p ORDER BY p.id`);
const findProject = database.prepare(`SELECT p.id, p.name, p.archived, p.default_task_priority AS defaultTaskPriority,
  (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id AND t.completed = 1) AS completedCount,
  (SELECT COUNT(*) FROM tasks t WHERE t.project_id = p.id) AS totalCount
  FROM projects p WHERE p.id = ?`);
const createProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
const listTasks = database.prepare('SELECT id, project_id AS projectId, title, completed, priority, due_date AS dueDate FROM tasks WHERE project_id = ? ORDER BY sort_order, id');
const createTask = database.prepare('INSERT INTO tasks (project_id, title, priority, sort_order) VALUES (?, ?, ?, COALESCE((SELECT MAX(sort_order) + 1 FROM tasks WHERE project_id = ?), 0))');
const moveTask = database.prepare('UPDATE tasks SET project_id = ?, sort_order = COALESCE((SELECT MAX(sort_order) + 1 FROM tasks WHERE project_id = ?), 0) WHERE id = ? AND project_id = ?');
const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');
const renameTask = database.prepare('UPDATE tasks SET title = ? WHERE id = ? AND project_id = ?');
const updatePriority = database.prepare("UPDATE tasks SET priority = ? WHERE id = ? AND project_id = ?");
const updateDueDate = database.prepare('UPDATE tasks SET due_date = ? WHERE id = ? AND project_id = ?');
const updateArchive = database.prepare('UPDATE projects SET archived = ? WHERE id = ?');
const renameProject = database.prepare('UPDATE projects SET name = ? WHERE id = ? AND archived = 0');
const updateDefaultPriority = database.prepare("UPDATE projects SET default_task_priority = ? WHERE id = ? AND archived = 0");

function sendJson(response, status, body) {
  response.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  response.end(JSON.stringify(body));
}

function isValidDate(value) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
  if (!match) return false;
  const year = Number(match[1]);
  const month = Number(match[2]);
  const day = Number(match[3]);
  if (year < 1 || month < 1 || month > 12) return false;
  const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
  const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
  return day >= 1 && day <= days[month - 1];
}

async function sendFile(response, filename, contentType) {
  try {
    const content = await readFile(join(root, filename));
    response.writeHead(200, { 'content-type': contentType });
    response.end(content);
  } catch {
    response.writeHead(500);
    response.end('Unable to load application');
  }
}

const server = createServer(async (request, response) => {
  const url = new URL(request.url, 'http://localhost');
  if (request.method === 'GET' && url.pathname === '/health') {
    return sendJson(response, 200, { status: 'ok' });
  }
  if (request.method === 'GET' && url.pathname === '/api/projects') {
    return sendJson(response, 200, listProjects.all().map(project => ({ ...project, archived: Boolean(project.archived) })));
  }
  if (request.method === 'POST' && url.pathname === '/api/projects') {
    let body = '';
    for await (const chunk of request) body += chunk;
    let name;
    try {
      name = JSON.parse(body).name;
    } catch {
      return sendJson(response, 400, { error: 'Invalid request' });
    }
    if (typeof name !== 'string' || !name.trim()) {
      return sendJson(response, 400, { error: 'Project name is required' });
    }
    const trimmedName = name.trim();
    const result = createProject.run(trimmedName);
    return sendJson(response, 201, { id: Number(result.lastInsertRowid), name: trimmedName });
  }
  const projectMatch = url.pathname.match(/^\/api\/projects\/(\d+)$/);
  if (request.method === 'PATCH' && projectMatch) {
    let body;
    try { body = await readRequestJson(request); } catch { return sendJson(response, 400, { error: 'Invalid request' }); }
    if (typeof body.name === 'string') {
      if (!body.name.trim()) return sendJson(response, 400, { error: 'Project name is required' });
      const result = renameProject.run(body.name.trim(), Number(projectMatch[1]));
      return result.changes ? sendJson(response, 200, { ok: true }) : sendJson(response, 404, { error: 'Active project not found' });
    }
    if (typeof body.defaultTaskPriority === 'string') {
      if (!['Low', 'Normal', 'High'].includes(body.defaultTaskPriority)) return sendJson(response, 400, { error: 'Invalid default task priority' });
      const result = updateDefaultPriority.run(body.defaultTaskPriority, Number(projectMatch[1]));
      return result.changes ? sendJson(response, 200, { ok: true }) : sendJson(response, 404, { error: 'Active project not found' });
    }
    if (typeof body.archived !== 'boolean') return sendJson(response, 400, { error: 'Invalid archive state' });
    const result = updateArchive.run(body.archived ? 1 : 0, Number(projectMatch[1]));
    return result.changes ? sendJson(response, 200, { ok: true }) : sendJson(response, 404, { error: 'Project not found' });
  }
  if (request.method === 'GET' && projectMatch) {
    const project = findProject.get(Number(projectMatch[1]));
    return project ? sendJson(response, 200, { ...project, archived: Boolean(project.archived) }) : sendJson(response, 404, { error: 'Project not found' });
  }
  const tasksMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks$/);
  if (tasksMatch) {
    const projectId = Number(tasksMatch[1]);
    if (!findProject.get(projectId)) return sendJson(response, 404, { error: 'Project not found' });
    if (request.method === 'GET') return sendJson(response, 200, listTasks.all(projectId).map(task => ({ ...task, completed: Boolean(task.completed) })));
    if (request.method === 'POST') {
      let body;
      try { body = await readRequestJson(request); } catch { return sendJson(response, 400, { error: 'Invalid request' }); }
      if (typeof body.title !== 'string' || !body.title.trim()) return sendJson(response, 400, { error: 'Task title is required' });
      const title = body.title.trim();
      const priority = findProject.get(projectId).defaultTaskPriority;
      const result = createTask.run(projectId, title, priority, projectId);
      return sendJson(response, 201, { id: Number(result.lastInsertRowid), projectId, title, completed: false, priority });
    }
  }
  const taskMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)$/);
  const moveMatch = url.pathname.match(/^\/api\/projects\/(\d+)\/tasks\/(\d+)\/move$/);
  if (request.method === 'POST' && moveMatch) {
    const sourceId = Number(moveMatch[1]);
    const taskId = Number(moveMatch[2]);
    let body;
    try { body = await readRequestJson(request); } catch { return sendJson(response, 400, { error: 'Invalid request' }); }
    const source = findProject.get(sourceId);
    const destinationId = Number(body.destinationProjectId);
    const destination = findProject.get(destinationId);
    if (!source || source.archived || !destination || destination.archived || sourceId === destinationId) {
      return sendJson(response, 400, { error: 'Invalid destination project' });
    }
    const result = moveTask.run(destinationId, destinationId, taskId, sourceId);
    return result.changes ? sendJson(response, 200, { ok: true }) : sendJson(response, 404, { error: 'Task not found' });
  }
  if (request.method === 'PATCH' && taskMatch) {
    const projectId = Number(taskMatch[1]);
    const taskId = Number(taskMatch[2]);
    let body;
    try { body = await readRequestJson(request); } catch { return sendJson(response, 400, { error: 'Invalid request' }); }
    if (typeof body.title === 'string') {
      if (!body.title.trim()) return sendJson(response, 400, { error: 'Task title is required' });
      const result = renameTask.run(body.title.trim(), taskId, projectId);
      return result.changes ? sendJson(response, 200, { ok: true }) : sendJson(response, 404, { error: 'Task not found' });
    }
    if (typeof body.priority === 'string') {
      if (!['Low', 'Normal', 'High'].includes(body.priority)) return sendJson(response, 400, { error: 'Invalid task priority' });
      const result = updatePriority.run(body.priority, taskId, projectId);
      return result.changes ? sendJson(response, 200, { ok: true }) : sendJson(response, 404, { error: 'Task not found' });
    }
    if (typeof body.dueDate === 'string') {
      const dueDate = body.dueDate.trim();
      if (dueDate && !isValidDate(dueDate)) return sendJson(response, 400, { error: 'Due date must be a valid YYYY-MM-DD date' });
      const result = updateDueDate.run(dueDate || null, taskId, projectId);
      return result.changes ? sendJson(response, 200, { ok: true, dueDate: dueDate || null }) : sendJson(response, 404, { error: 'Task not found' });
    }
    if (typeof body.completed !== 'boolean') return sendJson(response, 400, { error: 'Invalid completion state' });
    const result = updateTask.run(body.completed ? 1 : 0, taskId, projectId);
    return result.changes ? sendJson(response, 200, { ok: true }) : sendJson(response, 404, { error: 'Task not found' });
  }
  if (request.method === 'GET' && url.pathname === '/app.js') {
    return sendFile(response, 'app.js', 'text/javascript; charset=utf-8');
  }
  if (request.method === 'GET' && (url.pathname === '/' || /^\/projects\/\d+$/.test(url.pathname))) {
    return sendFile(response, 'index.html', 'text/html; charset=utf-8');
  }
  response.writeHead(404, { 'content-type': 'text/plain; charset=utf-8' });
  response.end('Not found');
});

async function readRequestJson(request) {
  let body = '';
  for await (const chunk of request) body += chunk;
  return JSON.parse(body);
}

const port = Number(process.env.PORT || 8080);
server.listen(port, '0.0.0.0');
const app = document.querySelector('#app');

function element(tag, text, attributes = {}) {
  const node = document.createElement(tag);
  if (text !== undefined) node.textContent = text;
  for (const [name, value] of Object.entries(attributes)) node.setAttribute(name, value);
  return node;
}

async function loadProjects() {
  const response = await fetch('/api/projects');
  if (!response.ok) throw new Error('Could not load projects');
  return response.json();
}

function projectRow(project, refresh) {
  const row = element('div', undefined, { 'data-testid': 'project-row', class: 'project-row' });
  row.append(element('span', project.name, { class: 'project-name' }));
  row.append(element('span', `${project.completedCount}/${project.totalCount} completed`, { 'data-testid': 'project-summary' }));
  const open = element('button', 'Open project', { type: 'button' });
  open.addEventListener('click', () => {
    history.pushState({}, '', `/projects/${project.id}`);
    renderProject(project.id);
  });
  row.append(open);
  if (project.archived) {
    const restore = element('button', 'Restore project', { type: 'button' });
    restore.addEventListener('click', async () => {
      await fetch(`/api/projects/${project.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ archived: false }) });
      refresh();
    });
    row.append(restore);
  } else {
    const archive = element('button', 'Archive project', { type: 'button' });
    archive.addEventListener('click', async () => {
      await fetch(`/api/projects/${project.id}`, { method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ archived: true }) });
      refresh();
    });
    row.append(archive);
  }
  return row;
}

async function renderList() {
  app.replaceChildren();
  app.append(element('h1', 'Workboard'));

  const form = element('form');
  const input = element('input', undefined, { type: 'text', 'aria-label': 'Project name', autocomplete: 'off' });
  const submit = element('button', 'Create project', { type: 'submit' });
  form.append(input, submit);
  const alert = element('p', '', { id: 'alert', role: 'alert', hidden: '' });
  const projects = element('section', undefined, { id: 'projects', 'aria-label': 'Projects' });
  const filter = element('select', undefined, { 'aria-label': 'Project filter' });
  filter.append(element('option', 'Active', { value: 'active' }), element('option', 'Archived', { value: 'archived' }));
  app.append(form, alert, filter, projects);

  const drawProjects = async () => {
    const allProjects = await loadProjects();
    const rows = document.createDocumentFragment();
    for (const project of allProjects) {
      if (project.archived !== (filter.value === 'archived')) continue;
      rows.append(projectRow(project, drawProjects));
    }
    projects.replaceChildren(rows);
  };
  filter.addEventListener('change', drawProjects);

  form.addEventListener('submit', async (event) => {
    event.preventDefault();
    const name = input.value.trim();
    if (!name) {
      alert.textContent = 'Project name is required';
      alert.hidden = false;
      return;
    }
    alert.textContent = '';
    alert.hidden = true;
    const response = await fetch('/api/projects', {
      method: 'POST',
      headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ name }),
    });
    if (!response.ok) {
      alert.textContent = 'Project name is required';
      alert.hidden = false;
      return;
    }
    const project = await response.json();
    input.value = '';
    await drawProjects();
  });

  await drawProjects();
}

async function renderProject(id) {
  const response = await fetch(`/api/projects/${encodeURIComponent(id)}`);
  if (!response.ok) {
    history.replaceState({}, '', '/');
    return renderList();
  }
  const project = await response.json();
  const projectListResponse = await fetch('/api/projects');
  const projectChoices = projectListResponse.ok ? await projectListResponse.json() : [];
  const view = element('section', undefined, { id: 'project-view' });
  view.append(element('h1', project.name));
  if (project.archived) view.append(element('p', 'Archived project'));
  const back = element('button', 'Projects', { type: 'button' });
  back.addEventListener('click', () => {
    history.pushState({}, '', '/');
    renderList();
  });
  const renameForm = element('form');
  const renameInput = element('input', undefined, { type: 'text', 'aria-label': 'New project name', autocomplete: 'off' });
  const renameButton = element('button', 'Rename project', { type: 'submit' });
  renameInput.disabled = project.archived;
  renameButton.disabled = project.archived;
  renameForm.append(renameInput, renameButton);
  const renameAlert = element('p', '', { role: 'alert', hidden: '' });
  renameForm.addEventListener('submit', async event => {
    event.preventDefault();
    const name = renameInput.value.trim();
    if (!name) {
      renameAlert.textContent = 'Project name is required';
      renameAlert.hidden = false;
      return;
    }
    const result = await fetch(`/api/projects/${id}`, {
      method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ name }),
    });
    if (!result.ok) {
      renameAlert.textContent = 'Project name is required';
      renameAlert.hidden = false;
      return;
    }
    project.name = name;
    view.querySelector('h1').textContent = name;
  });
  const form = element('form');
  const input = element('input', undefined, { type: 'text', 'aria-label': 'Task title', autocomplete: 'off' });
  const submit = element('button', 'Create task', { type: 'submit' });
  if (project.archived) {
    input.disabled = true;
    submit.disabled = true;
  }
  form.append(input, submit);
  const alert = element('p', '', { role: 'alert', hidden: '' });
  const filter = element('select', undefined, { 'aria-label': 'Task filter' });
  for (const [value, label] of [['all', 'All'], ['open', 'Open'], ['completed', 'Completed']]) {
    filter.append(element('option', label, { value }));
  }
  const priorityFilter = element('select', undefined, { 'aria-label': 'Priority filter' });
  for (const value of ['All', 'Low', 'Normal', 'High']) {
    priorityFilter.append(element('option', value, { value }));
  }
  const dueRangeForm = element('form');
  const dueFromInput = element('input', undefined, { type: 'text', 'aria-label': 'Due from', placeholder: 'YYYY-MM-DD', autocomplete: 'off' });
  const dueThroughInput = element('input', undefined, { type: 'text', 'aria-label': 'Due through', placeholder: 'YYYY-MM-DD', autocomplete: 'off' });
  const applyDueRange = element('button', 'Apply due range', { type: 'submit' });
  dueRangeForm.append(dueFromInput, dueThroughInput, applyDueRange);
  const dueRangeAlert = element('p', '', { role: 'alert', hidden: '' });
  let appliedDueFrom = '';
  let appliedDueThrough = '';
  const validDate = value => {
    const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(value);
    if (!match) return false;
    const year = Number(match[1]);
    const month = Number(match[2]);
    const day = Number(match[3]);
    if (year < 1 || month < 1 || month > 12) return false;
    const leap = year % 4 === 0 && (year % 100 !== 0 || year % 400 === 0);
    const days = [31, leap ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];
    return day >= 1 && day <= days[month - 1];
  };
  dueRangeForm.addEventListener('submit', event => {
    event.preventDefault();
    const from = dueFromInput.value.trim();
    const through = dueThroughInput.value.trim();
    if ((from && !validDate(from)) || (through && !validDate(through))) {
      dueRangeAlert.textContent = 'Due range must use valid YYYY-MM-DD dates';
      dueRangeAlert.hidden = false;
      return;
    }
    if (from && through && from > through) {
      dueRangeAlert.textContent = 'Due from must not be after Due through';
      dueRangeAlert.hidden = false;
      return;
    }
    appliedDueFrom = from;
    appliedDueThrough = through;
    dueRangeAlert.textContent = '';
    dueRangeAlert.hidden = true;
    drawTasks();
  });
  const defaultPriority = element('select', undefined, { 'aria-label': 'Default task priority' });
  for (const value of ['Low', 'Normal', 'High']) {
    defaultPriority.append(element('option', value, { value }));
  }
  defaultPriority.value = project.defaultTaskPriority || 'Normal';
  defaultPriority.disabled = project.archived;
  defaultPriority.addEventListener('change', async () => {
    const previousPriority = project.defaultTaskPriority || 'Normal';
    const result = await fetch(`/api/projects/${id}`, {
      method: 'PATCH', headers: { 'content-type': 'application/json' },
      body: JSON.stringify({ defaultTaskPriority: defaultPriority.value }),
    });
    if (result.ok) project.defaultTaskPriority = defaultPriority.value;
    else defaultPriority.value = previousPriority;
  });
  const tasks = element('section', undefined, { 'aria-label': 'Tasks' });
  tasks.className = 'task-list';
  let taskData = [];
  const drawTasks = () => {
    tasks.replaceChildren();
    const mode = filter.value;
    const selectedPriority = priorityFilter.value;
    for (const task of taskData) {
      if (mode === 'open' && task.completed || mode === 'completed' && !task.completed) continue;
      if (selectedPriority !== 'All' && task.priority !== selectedPriority) continue;
      if ((appliedDueFrom || appliedDueThrough) && !task.dueDate) continue;
      if (task.dueDate && appliedDueFrom && task.dueDate < appliedDueFrom) continue;
      if (task.dueDate && appliedDueThrough && task.dueDate > appliedDueThrough) continue;
      const row = element('div', undefined, { 'data-testid': 'task-row', class: 'task-row' });
      row.append(element('span', task.title));
      const checkbox = element('input', undefined, { type: 'checkbox', 'aria-label': `Complete ${task.title}` });
      checkbox.checked = task.completed;
      checkbox.disabled = project.archived;
      checkbox.addEventListener('change', async () => {
        const result = await fetch(`/api/projects/${id}/tasks/${task.id}`, {
          method: 'PATCH', headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ completed: checkbox.checked }),
        });
        if (result.ok) {
          task.completed = checkbox.checked;
          drawTasks();
        } else {
          checkbox.checked = task.completed;
        }
      });
      row.append(checkbox);
      const priority = element('select', undefined, { 'aria-label': 'Task priority' });
      for (const value of ['Low', 'Normal', 'High']) {
        priority.append(element('option', value, { value }));
      }
      priority.value = task.priority || 'Normal';
      priority.disabled = project.archived;
      priority.addEventListener('change', async () => {
        const previousPriority = task.priority || 'Normal';
        const result = await fetch(`/api/projects/${id}/tasks/${task.id}`, {
          method: 'PATCH', headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ priority: priority.value }),
        });
        if (result.ok) {
          task.priority = priority.value;
          drawTasks();
        }
        else priority.value = previousPriority;
      });
      row.append(priority);
      const renameForm = element('form');
      const renameInput = element('input', undefined, { type: 'text', 'aria-label': 'New task title', autocomplete: 'off' });
      const renameButton = element('button', 'Rename task', { type: 'submit' });
      renameInput.disabled = project.archived;
      renameButton.disabled = project.archived;
      const renameAlert = element('span', '', { role: 'alert', hidden: '' });
      renameForm.append(renameInput, renameButton);
      renameForm.addEventListener('submit', async event => {
        event.preventDefault();
        const title = renameInput.value.trim();
        if (!title) {
          renameAlert.textContent = 'Task title is required';
          renameAlert.hidden = false;
          return;
        }
        const result = await fetch(`/api/projects/${id}/tasks/${task.id}`, {
          method: 'PATCH', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ title }),
        });
        if (!result.ok) {
          renameAlert.textContent = 'Task title is required';
          renameAlert.hidden = false;
          return;
        }
        task.title = title;
        drawTasks();
      });
      row.append(renameForm, renameAlert);
      const dueDateForm = element('form');
      const dueDateInput = element('input', undefined, { type: 'text', 'aria-label': 'Task due date', placeholder: 'YYYY-MM-DD', autocomplete: 'off' });
      dueDateInput.value = task.dueDate || '';
      const dueDateButton = element('button', 'Save due date', { type: 'submit' });
      dueDateInput.disabled = project.archived;
      dueDateButton.disabled = project.archived;
      const dueDateAlert = element('span', '', { role: 'alert', hidden: '' });
      dueDateForm.append(dueDateInput, dueDateButton);
      dueDateForm.addEventListener('submit', async event => {
        event.preventDefault();
        const dueDate = dueDateInput.value.trim();
        const result = await fetch(`/api/projects/${id}/tasks/${task.id}`, {
          method: 'PATCH', headers: { 'content-type': 'application/json' },
          body: JSON.stringify({ dueDate }),
        });
        if (!result.ok) {
          dueDateAlert.textContent = 'Due date must be a valid YYYY-MM-DD date';
          dueDateAlert.hidden = false;
          dueDateInput.value = task.dueDate || '';
          return;
        }
        const saved = await result.json();
        task.dueDate = saved.dueDate;
        dueDateAlert.hidden = true;
        drawTasks();
      });
      row.append(dueDateForm, dueDateAlert);
